BEGIN;

DELETE FROM questions WHERE topic = 'The Nervous System' AND subtopic IN ('CNS & Spinal Cord Organization', 'Neuron Functional Types', 'PNS: Somatic vs Autonomic', 'Reflex Arcs', 'Sympathetic vs Parasympathetic');

-- Q1 [Neuron Functional Types | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub1$Neuron Functional Types$sub1$, $qt1$A person's fingertip brushes a warm mug, and a touch receptor in the skin fires; the resulting signal travels along an axon from the skin through a dorsal root into the spinal cord. The neuron carrying this signal is BEST classified as:$qt1$, $op1$[{"label": "A", "text": "A sensory (afferent) neuron, which carries information from the skin receptor toward the central nervous system"}, {"label": "B", "text": "A motor (efferent) neuron, which carries information from the skin receptor toward the central nervous system"}, {"label": "C", "text": "An interneuron, which carries information from the skin receptor toward the central nervous system"}, {"label": "D", "text": "A preganglionic autonomic neuron, which carries information from the skin receptor toward the central nervous system"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is A because the neuron that conducts a signal from a peripheral receptor inward to the spinal cord is, by definition, a sensory (afferent) neuron. OpenStax Anatomy and Physiology states that in a withdrawal response "Sensory receptors in the skin sense extreme temperature... This triggers an action potential, which travels along the sensory fiber from the skin, through the dorsal spinal root to the spinal cord," and that "Somatic reflexes involve sensory neurons that connect sensory receptors to the CNS." OpenStax Biology likewise notes that "Sensory neurons transmit sensory information from the skin, skeletal muscle, and sensory organs to the CNS," confirming that the afferent direction is receptor-to-central-nervous-system. The scenario describes exactly this inward path from a skin touch receptor through the dorsal root, so the neuron is sensory/afferent. (Choice A) is correct because the sensory (afferent) neuron is defined by carrying information from a peripheral receptor toward the CNS. (Choice B) is incorrect because a motor (efferent) neuron runs the opposite direction, "from the CNS to the muscles," not inward from a receptor. (Choice C) is incorrect because interneurons "connect two neurons" lying within the CNS rather than running in from a peripheral skin receptor. (Choice D) is incorrect because a preganglionic autonomic neuron is an output-side efferent class whose axon "represents the output from the CNS to the ganglion," not an afferent inflow from a receptor. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the directional definition that classifies a neuron carrying receptor input toward the CNS as sensory/afferent.$ex1$, 'easy', '3A', $cc1$Nervous System Organization$cc1$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a1B$Swapping the efferent (CNS-to-effector) direction for the afferent (receptor-to-CNS) direction$a1B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a1C$Treating an entirely-CNS-internal connector neuron as a peripheral inflow neuron$a1C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a1D$Substituting an output-side autonomic efferent class for the afferent sensory class$a1D$ FROM q;

-- Q2 [Neuron Functional Types | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub2$Neuron Functional Types$sub2$, $qt2$A neuroscientist labels a population of multipolar neurons confined to the gray matter of the spinal cord and finds that each labeled cell forms synapses only with other neurons, never directly contacting a sensory receptor or a muscle fiber. Which functional neuron type has the scientist labeled?$qt2$, $op2$[{"label": "A", "text": "Sensory (afferent) neurons, which lie between sensory and motor neurons and contact neither a receptor nor an effector"}, {"label": "B", "text": "Interneurons, which lie between sensory and motor neurons and contact neither a receptor nor an effector"}, {"label": "C", "text": "Motor (efferent) neurons, which lie between sensory and motor neurons and contact neither a receptor nor an effector"}, {"label": "D", "text": "Bipolar neurons, which lie between sensory and motor neurons and contact neither a receptor nor an effector"}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is B because interneurons are defined as the neurons that connect one neuron to another and lie in between the sensory (input) and motor (output) sides, so they touch neither a receptor nor an effector. OpenStax Biology 2e states that "Gray matter is also composed of interneurons, which connect two neurons each located in different parts of the body," and that motor neurons "are usually stimulated by interneurons within the spinal cord," placing the interneuron between the sensory input and the motor output. A cell that synapses only with other neurons, never directly contacting a sensory receptor or a muscle fiber, fits this intermediary wiring role exactly, which is what the labeling experiment reveals. (Choice A) Sensory (afferent) neurons are the receptor-side input class that "transmit sensory information from the skin, skeletal muscle, and sensory organs to the CNS," so they do contact receptors and are not the in-between connector. (Choice B) Interneurons connect one neuron to another and lie between sensory and motor neurons, matching cells that synapse only with other neurons—this is correct. (Choice C) Motor (efferent) neurons are the effector-side output class that "transmit messages about desired movement from the CNS to the muscles to make them contract," so they do contact effectors and are not the in-between connector. (Choice D) Bipolar neurons are a structural/polarity class that is "not very common," found "mainly in the olfactory epithelium... and as part of the retina," so they are defined by cell shape rather than by serving as the intermediary functional type. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defining functional role of the interneuron within the basic organization of the nervous system.$ex2$, 'easy', '3A', $cc2$Nervous System Organization$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a2A$Naming the receptor-side input class (sensory/afferent) as the in-between connector instead of the intermediary type$a2A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a2C$Naming the effector-side output class (motor/efferent) as the in-between connector instead of the intermediary type$a2C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a2D$Substituting a structural/polarity class (bipolar) defined by cell shape for the functional intermediary type$a2D$ FROM q;

-- Q3 [Neuron Functional Types | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub3$Neuron Functional Types$sub3$, $qt3$A thermoregulatory center in the CNS detects rising core temperature and issues a command that travels out along a peripheral nerve fiber to an eccrine sweat gland in the skin, triggering it to secrete sweat. A physiologist asks a student to classify, by function, the neuron whose fiber carries this outgoing command to the gland. The neuron is best classified as:$qt3$, $op3$[{"label": "A", "text": "A sensory (afferent) neuron, because afferent fibers carry the secretory command from the CNS out to the gland"}, {"label": "B", "text": "An interneuron, because interneurons project out of the CNS to drive the gland directly"}, {"label": "C", "text": "A motor (efferent) neuron, because efferent output carries commands from the CNS to effectors that include glands as well as muscles"}, {"label": "D", "text": "A motor (efferent) neuron, because efferent output reaches skeletal muscle only and never reaches glands"}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is C because a fiber carrying an outgoing command from the CNS to an effector is, by definition, a motor (efferent) neuron, and the set of effectors that motor neurons reach includes glands, not just muscle. OpenStax Biology 2e states that "Motor neurons transmit messages about desired movement from the CNS to the muscles," establishing the outward, CNS-to-effector direction that defines the efferent class. OpenStax Anatomy & Physiology 2e broadens that target set, noting that motor "responses also include the neural control of glands in the body as well, such as the production and secretion of sweat by the eccrine and merocrine sweat glands," and that "the motor output extends to smooth and cardiac muscle as well as glandular tissue." Because the command here exits the CNS and acts on a secretory gland, the carrying neuron is a motor (efferent) neuron whose effector happens to be a gland. (Choice A) A sensory (afferent) neuron carries information the opposite way—"Sensory neurons transmit sensory information from the skin, skeletal muscle, and sensory organs to the CNS"—so it could not carry an outgoing secretory command. (Choice B) An interneuron does not exit the CNS to an effector; interneurons "connect two neurons each located in different parts of the body," so they relay between neurons rather than synapsing onto the gland. (Choice C) is correct because efferent (motor) output is precisely the CNS-to-effector pathway, and effectors include glandular tissue such as sweat glands. (Choice D) correctly names the motor class but wrongly restricts its targets to skeletal muscle, contradicting the text that motor output reaches glandular tissue and that sweat glands are driven by this output. This is a Scientific Reasoning and Problem Solving question because the student must take a described scenario—a command exiting the CNS to a secretory gland—and reason from the directional and target-based definitions of neuron function to assign the correct functional class.$ex3$, 'medium', '3A', $cc3$Nervous System Organization$cc3$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a3A$Flipping the afferent (toward-CNS) direction to claim sensory fibers carry an outgoing command$a3A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a3B$Treating interneurons as cells that exit the CNS to contact an effector directly$a3B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a3D$Correctly naming the motor class but falsely restricting its effector targets to skeletal muscle only$a3D$ FROM q;

-- Q4 [Neuron Functional Types | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub4$Neuron Functional Types$sub4$, $qt4$A child touches a hot stove, and the polysynaptic withdrawal reflex pulls the hand away before the brain registers pain. A neurophysiologist traces the spinal arc and finds that the incoming neuron carrying the burn signal does not synapse directly onto the outgoing neuron that drives muscle contraction; instead, a third neuron, with its cell body in the spinal cord gray matter, sits between them and passes the signal along. Which functional neuron type occupies this middle, relaying position?$qt4$, $op4$[{"label": "A", "text": "A second sensory (afferent) neuron, which sits between the incoming sensory neuron and the outgoing motor neuron and relays the signal"}, {"label": "B", "text": "A preganglionic autonomic neuron, which sits between the incoming sensory neuron and the outgoing motor neuron and relays the signal"}, {"label": "C", "text": "A second motor (efferent) neuron, which sits between the incoming sensory neuron and the outgoing motor neuron and relays the signal"}, {"label": "D", "text": "An interneuron, which sits between the incoming sensory neuron and the outgoing motor neuron and relays the signal"}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is D because the neuron that occupies the middle, integrating position in a polysynaptic spinal reflex—connecting an incoming sensory neuron to an outgoing motor neuron entirely within the CNS—is by definition an interneuron. OpenStax Biology 2e states that the spinal cord gray matter "is also composed of interneurons, which connect two neurons each located in different parts of the body," and OpenStax Anatomy & Physiology 2e describes the hot-stove withdrawal reflex precisely: the interneuron's "cell body is located in the dorsal horn of the spinal cord," it "receives a synapse from the axon of the sensory neuron," and it then acts on "the motor neuron." Because the scenario specifies that the sensory neuron does not synapse directly onto the motor neuron, the relay must be a neuron that is neither purely afferent (input) nor purely efferent (output), which is the interneuron. (Choice A) A second sensory (afferent) neuron is wrong because sensory neurons "transmit sensory information from the skin... to the CNS"—they are inflow neurons, not the integrating link between input and output. (Choice B) A preganglionic autonomic neuron is wrong because, as part of the autonomic motor pathway, "a preganglionic neuron (originating in the CNS) synapses to a neuron in a ganglion," driving visceral output rather than relaying a somatic spinal reflex. (Choice C) A second motor (efferent) neuron is wrong because motor neurons "transmit messages about desired movement from the CNS to the muscles," so inserting another efferent neuron mislabels the integrating middle element as an output neuron. (Choice D) An interneuron is correct because it is the CNS neuron that, by definition, connects the sensory input to the motor output within the spinal cord. This is a Scientific Reasoning and Problem Solving question because the test-taker must apply the functional-classification scheme of neurons to a described reflex arc and infer, from the stated wiring, which neuron type can occupy the integrating position between afferent and efferent limbs.$ex4$, 'medium', '3A', $cc4$Nervous System Organization$cc4$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a4A$A second afferent neuron would still be an inflow (input) neuron and could not serve as the integrating link between sensory input and motor output.$a4A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a4B$Preganglionic neurons belong to the autonomic motor pathway feeding ganglia, not the somatic spinal reflex relay between sensory and motor neurons.$a4B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a4C$Inserting another efferent neuron mislabels the integrating middle element—which is an interneuron—as an output neuron.$a4C$ FROM q;

-- Q5 [Neuron Functional Types | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub5$Neuron Functional Types$sub5$, $qt5$A lesion selectively destroys the axons entering the spinal cord through the dorsal root of one spinal nerve while leaving the corresponding ventral root completely intact. A clinician predicts the resulting deficit in the body region served by that nerve.$qt5$, $op5$[{"label": "A", "text": "Voluntary movement is lost while sensation is preserved, because the dorsal root carries the efferent motor axons whereas sensory input enters intact through the ventral root."}, {"label": "B", "text": "Sensation is lost while voluntary movement is preserved, because the dorsal root carries the afferent sensory axons whereas motor output exits intact through the ventral root."}, {"label": "C", "text": "Both sensation and voluntary movement are lost, because the dorsal root carries the mixed sensory and motor axons that supply that region of the body."}, {"label": "D", "text": "Sensation is lost while reflexive sweating increases, because the lesion removes afferent input but releases the sympathetic efferent neurons that exit through the dorsal root."}]$op5$::jsonb, 'B', $ex5$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is B because the dorsal root carries only afferent (sensory) axons into the spinal cord, so destroying it abolishes sensation from that region, while the ventral root—which carries the motor axons leaving the cord—is untouched, so voluntary movement is preserved. As the spinal nerve nears the cord it splits into dorsal and ventral roots, and the text states that "The dorsal root contains only the axons of sensory neurons, whereas the ventral roots contain only the axons of the motor neurons." Motor neurons "have cell bodies in the ventral gray matter of the spinal cord that project to muscle through the ventral root," so a deficit confined to the dorsal root cannot interrupt that motor outflow. The result is a selective loss of sensory inflow with intact efferent (motor) outflow. (Choice A) is reversed: the dorsal root is sensory/afferent and the ventral root is motor/efferent, so a dorsal-root lesion spares movement rather than abolishing it. (Choice B) is correct because dorsal-root destruction removes only afferent fibers while the motor-bearing ventral root remains intact. (Choice C) confuses the whole spinal nerve—which is a mixed sensory-and-motor structure—with the dorsal root specifically, which carries only afferent fibers, so motor function is spared. (Choice D) is wrong because autonomic (including sympathetic) motor fibers emerge through the ventral root, not the dorsal root, so a dorsal-root lesion cannot disinhibit them to raise sweating. This is a Scientific Reasoning and Problem Solving question because it requires mapping the sensory-versus-motor identity of root anatomy onto a lesion scenario to predict which function is lost and which is preserved.$ex5$, 'hard', '3A', $cc5$Nervous System Organization$cc5$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a5A$Swapping the afferent/efferent identity of the dorsal and ventral roots$a5A$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a5C$Treating the afferent-only dorsal root as if it were the mixed whole spinal nerve$a5C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a5D$Believing sympathetic efferent fibers leave the cord through the dorsal rather than the ventral root$a5D$ FROM q;

-- Q6 [CNS & Spinal Cord Organization | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub6$CNS & Spinal Cord Organization$sub6$, $qt6$A neuroanatomy student is asked to label only the structures that belong to the central nervous system on a diagram of the human nervous system, leaving every peripheral structure unlabeled. Which pair of structures should the student label as constituting the central nervous system?$qt6$, $op6$[{"label": "A", "text": "The spinal cord together with the peripheral spinal nerves that branch from it"}, {"label": "B", "text": "The brain together with the cranial and spinal nerves that extend from it"}, {"label": "C", "text": "The brain together with the spinal cord"}, {"label": "D", "text": "The brain and spinal cord together with the dorsal root ganglion on each spinal nerve"}]$op6$::jsonb, 'C', $ex6$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is C because the central nervous system is defined as exactly two structures, the brain and the spinal cord, with everything else belonging to the peripheral nervous system. OpenStax Anatomy & Physiology states that \"The central nervous system (CNS) is the brain and spinal cord, and the peripheral nervous system (PNS) is everything else,\" and OpenStax Biology likewise notes that \"The vertebrate central nervous system contains the brain and the spinal cord.\" Nerves and ganglia are the structures of the PNS, which is \"on the periphery—meaning beyond the brain and spinal cord,\" so any pair that adds nerves or ganglia overcounts the CNS. (Choice A) is incorrect because the peripheral spinal nerves are PNS structures, not part of the CNS, even though the spinal cord itself is. (Choice B) is incorrect because the cranial and spinal nerves are nerves of the PNS, which \"transmit sensory information from skin and muscle to the CNS and motor commands from the CNS to the muscles,\" rather than CNS components. (Choice C) is correct because the brain and the spinal cord are the two organs that together comprise the central nervous system. (Choice D) is incorrect because the dorsal (posterior) root ganglion is a peripheral ganglion whose sensory cell bodies merely \"extend into the CNS through the dorsal nerve root,\" so it lies in the PNS rather than within the CNS. This is a Knowledge of Scientific Concepts and Principles question because it requires directly recalling the anatomical definition of the central nervous system and distinguishing it from peripheral nerves and ganglia.$ex6$, 'easy', '3A', $cc6$Nervous System Organization$cc6$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a6A$Treats PNS nerves branching from a CNS organ as themselves part of the CNS$a6A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a6B$Names real cranial/spinal nerves but assigns these PNS structures to the CNS$a6B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a6D$Correct CNS pair plus an extra peripheral ganglion that does not belong to the CNS$a6D$ FROM q;

-- Q7 [CNS & Spinal Cord Organization | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub7$CNS & Spinal Cord Organization$sub7$, $qt7$A neurosurgeon selectively severs only the dorsal root of a single spinal nerve, leaving that same nerve's ventral root completely intact. For the body region served by that spinal nerve, which type of information is predicted to be blocked?$qt7$, $op7$[{"label": "A", "text": "Outgoing motor commands to skeletal muscles, because the dorsal root carries the axons of the somatic motor neurons"}, {"label": "B", "text": "Both incoming sensory input and outgoing motor commands, because each root carries an intermingled mix of sensory and motor axons"}, {"label": "C", "text": "Autonomic motor output to the viscera, because the dorsal root carries the preganglionic autonomic motor fibers"}, {"label": "D", "text": "Incoming sensory input from the periphery, because the dorsal root carries the axons of sensory neurons entering the cord"}]$op7$::jsonb, 'D', $ex7$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is D because the dorsal root contains only the sensory (afferent) axons entering the spinal cord, so cutting it abolishes sensory input from that region while the ventral root, which carries the motor (efferent) fibers, stays intact and keeps conducting motor commands. OpenStax Anatomy & Physiology 2e states that a spinal nerve's combined axons separate into two nerve roots, where the sensory axons enter the cord as the dorsal nerve root and the motor fibers, both somatic and autonomic, emerge as the ventral nerve root, establishing that the two modalities are anatomically segregated at the roots. Because the lesion is confined to the dorsal root, the surviving ventral root still conducts both somatic and autonomic motor output, so only the incoming sensory channel is interrupted. OpenStax Biology 2e corroborates this, placing sensory neuron cell bodies in the dorsal root ganglia while stating that motor neurons project to muscle through the ventral root. (Choice A) Motor output is preserved, not blocked, and it is the ventral root, not the dorsal root, that carries somatic motor axons. (Choice B) The roots are not mixed: the spinal nerve is combined only distal to the roots, which themselves segregate sensory fibers dorsally and motor fibers ventrally, so an intact ventral root keeps motor output running. (Choice C) Autonomic motor fibers also exit through the ventral root, not the dorsal root, so an intact ventral root preserves visceral motor output as well. (Choice D) The dorsal root carries only sensory axons entering the cord, so severing it selectively blocks incoming sensory input while sparing all motor output through the intact ventral root. This is a Scientific Reasoning and Problem Solving question because the student must apply the segregated dorsal-sensory/ventral-motor wiring of spinal roots to predict the specific functional deficit produced by a targeted experimental lesion.$ex7$, 'medium', '3A', $cc7$Nervous System Organization$cc7$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a7A$Swaps the dorsal=sensory / ventral=motor assignment, treating the dorsal root as the motor pathway$a7A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a7B$Believes sensory and motor axons are mixed within each root rather than segregated dorsal vs ventral$a7B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a7C$Correctly recalls autonomic motor outflow but misroutes it through the dorsal root instead of the ventral root$a7C$ FROM q;

-- Q8 [CNS & Spinal Cord Organization | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub8$CNS & Spinal Cord Organization$sub8$, $qt8$A neuroanatomist needs to locate the cell body of a spinal sensory neuron whose peripheral ending detects touch in the skin of the forearm and whose central axon enters the cord through the dorsal nerve root. Tracing the neuron back from its central axon, in which structure does she find the soma?$qt8$, $op8$[{"label": "A", "text": "In the anterior (ventral) horn of the spinal cord gray matter"}, {"label": "B", "text": "In the dorsal root ganglion, an enlargement of the dorsal nerve root just outside the cord"}, {"label": "C", "text": "In the lateral horn of the spinal cord gray matter"}, {"label": "D", "text": "In the posterior (dorsal) column of the spinal cord white matter"}]$op8$::jsonb, 'B', $ex8$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is B because the cell bodies of spinal sensory neurons reside in the dorsal root ganglion, an enlargement of the dorsal nerve root located just outside the spinal cord, not within the cord itself. The text states that the most common sensory ganglion "is a dorsal (posterior) root ganglion. These ganglia are the cell bodies of neurons with axons that are sensory endings in the periphery... and that extend into the CNS through the dorsal nerve root," and that "The ganglion is an enlargement of the nerve root." Because the sensory neuron's central process enters through the dorsal root, tracing it back leads outward to that swelling on the root, where the soma sits among satellite cells, rather than into any gray-matter horn or white-matter column inside the cord. (Choice A) The anterior (ventral) horn holds the cell bodies of multipolar motor neurons that drive skeletal muscle, not sensory somata, so it is the wrong location. (Choice B) Correct: the dorsal root ganglion, an enlargement of the dorsal nerve root, contains the cell bodies of the sensory neurons. (Choice C) The lateral horn contains cell bodies of autonomic (visceral) motor neurons, again a motor population rather than the somatosensory soma being traced. (Choice D) The posterior (dorsal) column is white matter composed of the ascending axons of these sensory neurons, but white-matter columns are tracts of axons, not the site of cell bodies. This is a Scientific Reasoning and Problem Solving question because the student must trace the neuron from its central axon back through the dorsal root to predict where its soma lies, distinguishing the cell-body location from the several gray- and white-matter regions that hold related but distinct cell populations or axons.$ex8$, 'medium', '3A', $cc8$Nervous System Organization$cc8$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a8A$Places the sensory soma in the motor-output horn (anterior/ventral horn holds skeletal motor cell bodies)$a8A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a8C$Names a real gray-matter horn that holds cell bodies, but autonomic motor ones (lateral horn), not somatosensory$a8C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a8D$Correct that the dorsal column carries this neuron's sensory axons, but it is a white-matter tract, not a site of cell bodies$a8D$ FROM q;

-- Q9 [CNS & Spinal Cord Organization | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub9$CNS & Spinal Cord Organization$sub9$, $qt9$During fetal development the spinal cord stops elongating after the first or second year, but the bony vertebral column continues to grow, so the lower spinal nerve roots lengthen and descend as the cauda equina. A neurologist needs to predict the vertebral level at which the sacral region of the spinal cord itself is found in an adult. At which vertebral level does the sacral spinal cord segment lie?$qt9$, $op9$[{"label": "A", "text": "At the level of the sacral vertebrae, because each cord segment sits directly within its like-named vertebra"}, {"label": "B", "text": "At the level of the cervical vertebrae, because the cord is numbered from inferior to superior"}, {"label": "C", "text": "At the level of the upper lumbar vertebrae, because the cord does not extend the full length of the column and the lengthened lower roots descend as the cauda equina"}, {"label": "D", "text": "At the level of the lower coccygeal vertebrae, because the cord extends slightly beyond the inferior end of the vertebral column"}]$op9$::jsonb, 'C', $ex9$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is C because the spinal cord stops growing significantly after the first or second year while the vertebral column keeps lengthening, so a named cord segment ends up sitting higher than its like-named vertebra. The text states that "the spinal cord is not the full length of the vertebral column because the spinal cord does not grow significantly longer after the first or second year, but the skeleton continues to grow," and that the lengthened lower nerves form "a long bundle of nerves that resembles a horse's tail and is named the cauda equina," concluding that "the sacral spinal cord is at the level of the upper lumbar vertebral bones." Because the cord ends at the upper lumbar region and does not extend through the lower lumbar or sacral vertebrae, the sacral cord segment must lie at the upper lumbar level, with its sacral roots descending the rest of the way as the cauda equina. (Choice A) The sacral vertebral level is wrong because it assumes the cord and column stay length-matched so each segment sits within its like-named vertebra, which the differential-growth fact directly contradicts. (Choice B) The cervical level is wrong because it inverts the actual superior-to-inferior ordering of cord regions (cervical, then thoracic, lumbar, and finally sacral); the sacral region is most inferior, not most superior. (Choice C) The upper lumbar level is correct because the cord stops short of the full column length and the sacral roots descend as the cauda equina, placing the sacral cord segment at the upper lumbar vertebrae. (Choice D) The lower coccygeal level is wrong because the inferior end of the CNS sits at the upper lumbar region and the cord does not extend through the lower lumbar region, so the cord ends above—not below—the lumbar level. This is a Scientific Reasoning and Problem Solving question because it requires combining the differential-growth relationship between cord and column with the cauda equina mechanism to predict a specific anatomical level rather than recalling a single stated fact.$ex9$, 'hard', '3A', $cc9$Nervous System Organization$cc9$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
