UNION ALL SELECT id, 'B', 'reversed_relationship', $a9B$inverts the superior-to-inferior ordering of spinal cord regions$a9B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a9D$places the cord ending below the column when the cord actually ends above the lumbar level$a9D$ FROM q;

-- Q10 [CNS & Spinal Cord Organization | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub10$CNS & Spinal Cord Organization$sub10$, $qt10$A patient sustains a clean injury that severs only the ventral root of one spinal nerve on the left side, leaving the dorsal root of that same spinal nerve fully intact. A clinician examines the single body segment served by that spinal nerve. What pattern of deficit is the clinician MOST likely to find in that segment?$qt10$, $op10$[{"label": "A", "text": "Skin sensation from that area is lost, while skeletal-muscle movement is preserved, because the severed ventral root carries the incoming sensory axons of the spinal nerve."}, {"label": "B", "text": "Both skin sensation and skeletal-muscle movement in that area are lost, because the severed ventral root carries the mixed sensory and motor axons of the spinal nerve."}, {"label": "C", "text": "Skeletal-muscle movement is preserved, while autonomic control of the viscera in that area is lost, because the severed ventral root carries only the autonomic motor fibers of the spinal nerve."}, {"label": "D", "text": "Skeletal-muscle movement in that area is lost, while skin sensation is preserved, because the severed ventral root carries only the motor axons while sensory axons still enter through the intact dorsal root."}]$op10$::jsonb, 'D', $ex10$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is D because the ventral root carries only the motor (efferent) axons leaving the cord, so cutting it paralyzes the skeletal muscles of that segment, while the sensory (afferent) axons still reach the cord through the spared dorsal root, leaving skin sensation intact. As a spinal nerve nears the cord it splits into two roots: "The dorsal root contains only the axons of sensory neurons, whereas the ventral roots contain only the axons of the motor neurons," and "Motor neurons have cell bodies in the ventral gray matter of the spinal cord that project to muscle through the ventral root." Because the two roots are anatomically segregated, severing one selectively removes its single function while sparing the other. (Choice A) is reversed: the ventral root carries motor, not sensory, axons, so cutting it cannot abolish sensation while sparing movement. (Choice B) wrongly treats the root itself as mixed; although the spinal nerve "contains both sensory and motor axons," it splits into a purely sensory dorsal root and a purely motor ventral root, so a single root is not mixed. (Choice C) is only partly right, because the ventral root carries somatic motor axons in addition to autonomic ones—the sympathetic preganglionic axon "projects by way of the ventral spinal nerve root"—so somatic skeletal movement would also be lost, not preserved. (Choice D) correctly pairs motor paralysis with intact sensation, matching the exclusively motor content of the ventral root and the exclusively sensory content of the spared dorsal root. This is a Scientific Reasoning and Problem Solving question because it requires applying the segregated dorsal-sensory/ventral-motor organization of spinal roots to predict the specific functional deficit produced by a defined anatomical lesion.$ex10$, 'hard', '3A', $cc10$Nervous System Organization$cc10$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a10A$Swaps ventral=motor for ventral=sensory, predicting lost sensation with preserved movement$a10A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a10B$Treats the individual root as a mixed sensory-and-motor nerve rather than a purely motor root$a10B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a10C$Correctly notes the ventral root carries autonomic motor fibers but ignores that it also carries somatic motor fibers, so somatic movement would also fail$a10C$ FROM q;

-- Q11 [PNS: Somatic vs Autonomic | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub11$PNS: Somatic vs Autonomic$sub11$, $qt11$A neuroanatomist tracing every nerve that connects directly to the spinal cord, rather than to the brain, tallies them by vertebral region: cervical, thoracic, lumbar, sacral, and coccygeal. How many pairs of spinal nerves does this complete tally yield?$qt11$, $op11$[{"label": "A", "text": "12 pairs of spinal nerves"}, {"label": "B", "text": "31 pairs of spinal nerves"}, {"label": "C", "text": "43 pairs of spinal nerves"}, {"label": "D", "text": "30 pairs of spinal nerves"}]$op11$::jsonb, 'B', $ex11$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is B because the human peripheral nervous system contains exactly 31 pairs of spinal nerves, each named for the level of the spinal cord from which it emerges. OpenStax Anatomy & Physiology 2e states, \"There are 31 spinal nerves,\" and itemizes them as \"eight pairs of cervical nerves... twelve thoracic nerves... five pairs of lumbar nerves... five pairs of sacral nerves... and one pair of coccygeal nerves\" (8 + 12 + 5 + 5 + 1 = 31). OpenStax Biology 2e independently confirms that \"Each of the 31 spinal nerves (in humans) contains both sensory and motor axons.\" These spinal nerves are distinct from the 12 cranial nerves, which connect to the brain rather than the spinal cord. (Choice A) 12 pairs is the number of cranial nerves that \"emerge from or enter the skull,\" not the number of spinal nerves. (Choice B) 31 pairs is correct because summing the cervical, thoracic, lumbar, sacral, and coccygeal nerves yields exactly 31. (Choice C) 43 pairs erroneously adds the 31 spinal nerves to the 12 cranial nerves, but cranial nerves are not spinal nerves. (Choice D) 30 pairs drops the single coccygeal pair, undercounting the total by one. This is a Knowledge of Scientific Concepts and Principles question because it requires direct recall of the established number and regional breakdown of spinal nerves in the peripheral nervous system.$ex11$, 'easy', '3A', $cc11$Nervous System Organization$cc11$, 'biology', 1, 65
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a11A$Substitutes the count of cranial nerves (12) for the count of spinal nerves$a11A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a11C$Sums two separate categories (31 spinal + 12 cranial) into one erroneous total$a11C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a11D$Omits the single coccygeal pair, undercounting the otherwise-correct total by one$a11D$ FROM q;

-- Q12 [PNS: Somatic vs Autonomic | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub12$PNS: Somatic vs Autonomic$sub12$, $qt12$A neurologist contrasts two efferent commands leaving the spinal cord: one orders the biceps (a skeletal muscle) to contract, and the other orders the sinoatrial node of the heart to speed up. The neurologist asks which command reaches its effector through a single, uninterrupted motor neuron running from the spinal cord to the target, with no intervening synapse along the way.$qt12$, $op12$[{"label": "A", "text": "The autonomic command to the heart, because its preganglionic neuron travels uninterrupted from the cord to the organ"}, {"label": "B", "text": "Both commands, because every peripheral motor pathway uses exactly one neuron running from the CNS to its effector"}, {"label": "C", "text": "The somatic command to the biceps, because one lower motor neuron runs from the cord straight to the muscle"}, {"label": "D", "text": "Neither command, because all PNS motor output first relays through a ganglion before reaching its target"}]$op12$::jsonb, 'C', $ex12$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is C because the somatic motor pathway to skeletal muscle uses a single lower motor neuron that projects from the spinal cord directly to the muscle, whereas the autonomic pathway to the heart inserts a synapse in a ganglion, splitting the route into two neurons. OpenStax A&P 2e states that "the output of a somatic reflex is the lower motor neuron in the ventral horn of the spinal cord that projects directly to a skeletal muscle," while "the output of a visceral reflex is a two-step pathway starting with the preganglionic fiber... to a ganglion—followed by the postganglionic fiber projecting to a target effector." Because the autonomic command to the SA node must cross the preganglionic-to-postganglionic synapse in a ganglion, it is interrupted; only the somatic command to the biceps is carried uninterrupted by one neuron from cord to effector. (Choice A) is wrong because the autonomic preganglionic neuron does not travel uninterrupted to the organ—it synapses on a ganglionic (postganglionic) neuron, so the heart is reached by two neurons in series. (Choice B) is wrong because it reverses the autonomic rule by treating every peripheral motor pathway as one-neuron; the autonomic efferent branch is explicitly a two-neuron chain. (Choice C) is correct because the somatic lower motor neuron projects from the ventral horn directly to skeletal muscle with no intervening synapse, satisfying the single-uninterrupted-neuron condition. (Choice D) is wrong because it misapplies the autonomic ganglionic relay to somatic output; the somatic system provides output strictly to skeletal muscles via a single motor neuron and does not relay through a ganglion. This is a Scientific Reasoning and Problem Solving question because it requires applying the structural distinction between somatic and autonomic efferent wiring to a specific scenario to predict which command travels via one uninterrupted neuron.$ex12$, 'medium', '3A', $cc12$Nervous System Organization$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a12A$Autonomic preganglionic neuron treated as reaching the organ uninterrupted, ignoring the ganglionic synapse$a12A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a12B$Generalizes the somatic one-neuron rule to all pathways, reversing the two-neuron autonomic rule$a12B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a12D$Applies the autonomic ganglionic relay to somatic output, claiming all PNS motor passes through a ganglion$a12D$ FROM q;

-- Q13 [PNS: Somatic vs Autonomic | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub13$PNS: Somatic vs Autonomic$sub13$, $qt13$During a meal, the gastric glands lining a person's stomach increase their secretion of digestive enzymes without the person deciding to make that happen. A physiology student is asked to identify which functional division of the peripheral nervous system delivers the motor command driving this glandular response.$qt13$, $op13$[{"label": "A", "text": "The somatic nervous system, because it issues every motor command that occurs below the threshold of conscious awareness"}, {"label": "B", "text": "The somatic nervous system, because secretory glands and smooth muscle are among the effectors that its motor neurons innervate"}, {"label": "C", "text": "The sensory-somatic nervous system, because it carries the outgoing motor signal that triggers the gastric glands to secrete"}, {"label": "D", "text": "The autonomic nervous system, because secretion by internal glands is an involuntary response that regulates the body's internal organs"}]$op13$::jsonb, 'D', $ex13$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is D because gastric glands are internal glandular tissue, and motor control of glands is an involuntary, homeostatic function — exactly the domain the autonomic nervous system governs, not the somatic system. OpenStax states that "involuntary responses (contraction of smooth muscles, regulation of cardiac muscle, activation of glands)" are "governed by the autonomic nervous system," and that the autonomic system's "motor output extends to smooth and cardiac muscle as well as glandular tissue." The somatic nervous system, by contrast, has the "defining characteristic ... that it controls skeletal muscles," so glandular secretion cannot be a somatic motor output. Because the person does not consciously command enzyme release and the response serves digestion of internal organs, the autonomic division is the correct functional assignment. (Choice A) is wrong because lack of conscious awareness alone does not make a response somatic — some somatic motor responses (reflexes, learned habits) also occur without conscious decision, yet the somatic system still acts only on skeletal muscle, not glands. (Choice B) is wrong because glands and smooth muscle are not somatic effectors; the somatic nervous system's motor neurons innervate skeletal muscle, while glandular and smooth-muscle effectors belong to the autonomic system. (Choice C) is wrong because the sensory-somatic (somatic) division sends motor commands to skeletal muscles, not to glands, so it cannot be the path that drives gastric secretion. (Choice D) is correct because activation of glands is an involuntary motor output to internal organs, which the autonomic nervous system controls. This is a Scientific Reasoning and Problem Solving question because it requires applying the somatic-versus-autonomic effector distinction to a specific target tissue (gastric glands) and predicting which division must be responsible.$ex13$, 'medium', '3A', $cc13$Nervous System Organization$cc13$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a13A$Equates any below-conscious-awareness motor output with the somatic division, ignoring that the somatic system acts only on skeletal muscle$a13A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a13B$Assigns autonomic effectors (glands, smooth muscle) to the somatic division, reversing the correct effector-to-division mapping$a13B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a13C$Routes an autonomic glandular motor command through the somatic motor pathway, confusing which division carries the output step$a13C$ FROM q;

-- Q14 [PNS: Somatic vs Autonomic | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub14$PNS: Somatic vs Autonomic$sub14$, $qt14$A neurologist follows a single autonomic command as it leaves the central nervous system and travels out to the heart, then asks a student to predict the cellular wiring of this efferent limb and to contrast it with the somatic motor path that drives a skeletal muscle. Which prediction correctly describes the number of neurons in the autonomic chain to the heart and the location of the synapse between them?$qt14$, $op14$[{"label": "A", "text": "One neuron projects directly from the CNS to the heart with no intervening synapse, exactly as a somatic motor neuron reaches a skeletal muscle."}, {"label": "B", "text": "Two neurons act in series: a preganglionic neuron from the CNS synapses in a peripheral ganglion onto a postganglionic neuron that then reaches the heart."}, {"label": "C", "text": "Two neurons act in series, but their synapse occurs within the spinal cord, after which a single axon exits the CNS and runs directly to the heart."}, {"label": "D", "text": "Three neurons act in series, with a preganglionic, a postganglionic, and a third ganglionic neuron each separated by its own synapse before the heart is reached."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is B because the autonomic efferent path to a visceral target such as the heart is a two-neuron chain whose relay synapse lies outside the CNS, in a peripheral ganglion. OpenStax Anatomy & Physiology 2e states that the output of a visceral reflex 'is a two-step pathway starting with the preganglionic fiber emerging from a lateral horn neuron in the spinal cord, or a cranial nucleus neuron in the brain stem, to a ganglion—followed by the postganglionic fiber projecting to a target effector,' and OpenStax Biology 2e adds that 'a preganglionic neuron (originating in the CNS) synapses to a neuron in a ganglion that, in turn, synapses on the target organ.' This contrasts with the somatic motor path, whose 'output... is the lower motor neuron in the ventral horn of the spinal cord that projects directly to a skeletal muscle,' a single neuron with no intervening synapse. Thus the autonomic chain has exactly two neurons, and the synapse between them sits in a ganglion in the periphery, not in the CNS, and there is no third relay. (Choice A) is wrong because it imports the single-neuron, no-synapse somatic wiring onto an autonomic target, but the somatic 'projects directly' arrangement applies only to skeletal muscle, not the heart. (Choice B) is correct because the preganglionic-to-postganglionic, ganglion-relayed two-neuron chain is precisely how the CNS reaches cardiac muscle. (Choice C) is wrong because it keeps the correct neuron count but misplaces the relay synapse inside the spinal cord, whereas the text locates that synapse in a peripheral ganglion. (Choice D) is wrong because it invents a nonexistent third ganglionic neuron and extra synapse, while the pathway is explicitly a two-step (two-neuron) chain. This is a Scientific Reasoning and Problem Solving question because it requires the student to apply the structural rule for autonomic efferents to a specific organ and to distinguish it from somatic wiring by reasoning about both neuron count and synapse location rather than recalling a single fact.$ex14$, 'hard', '3A', $cc14$Nervous System Organization$cc14$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a14A$Applies the single-neuron, synapse-free somatic motor wiring to an autonomic (cardiac) target$a14A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a14C$Correct two-neuron count but places the relay synapse inside the CNS instead of a peripheral ganglion$a14C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a14D$Adds a nonexistent third ganglionic neuron and extra synapse to the two-neuron chain$a14D$ FROM q;

-- Q15 [PNS: Somatic vs Autonomic | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub15$PNS: Somatic vs Autonomic$sub15$, $qt15$A surgical injury destroys a peripheral autonomic ganglion that relays motor signals to a single abdominal organ, while sparing every other nerve in the region, including the somatic motor fibers running to the nearby skeletal muscles. A physiologist predicts the functional consequence by reasoning from where each motor pathway makes its synapse on the way from the central nervous system to its effector. What outcome should the physiologist expect?$qt15$, $op15$[{"label": "A", "text": "Involuntary autonomic control of the organ is lost while voluntary movement of the nearby skeletal muscle is preserved, because only the autonomic pathway relays through a peripheral ganglion."}, {"label": "B", "text": "Both involuntary control of the organ and voluntary movement of the nearby skeletal muscle are lost, because every peripheral motor fiber must pass through that ganglion to reach its effector."}, {"label": "C", "text": "Involuntary autonomic control of the organ is preserved while voluntary movement of the nearby skeletal muscle is lost, because only the somatic pathway relays through a peripheral ganglion."}, {"label": "D", "text": "Neither involuntary control of the organ nor voluntary movement of the nearby skeletal muscle is affected, because the ganglion houses only sensory cell bodies and carries no motor relay."}]$op15$::jsonb, 'A', $ex15$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is A because the autonomic motor pathway depends on a relay neuron sitting inside a peripheral ganglion, whereas the somatic motor pathway never synapses in such a ganglion. In the autonomic nervous system, "Signaling to the target tissue usually involves two synapses: a preganglionic neuron (originating in the CNS) synapses to a neuron in a ganglion that, in turn, synapses on the target organ," so destroying that ganglion removes the only relay and abolishes involuntary control of the organ. By contrast, the sensory-somatic system is built differently: "Unlike the autonomic nervous system, which has two synapses between the CNS and the target organ, sensory and motor neurons have only one synapse—one ending of the neuron is at the organ and the other directly contacts a CNS neuron," so the single somatic motor neuron reaching skeletal muscle never passes through a peripheral ganglion and is spared. (Choice A) is correct: the organ's involuntary control collapses because its ganglionic relay neuron is gone, while voluntary skeletal-muscle movement continues because that motor neuron runs uninterrupted from the cord to the muscle. (Choice B) is wrong because it incorrectly routes the somatic motor axon through the autonomic ganglion; the somatic motor neuron contacts the muscle directly without a peripheral relay. (Choice C) reverses the actual dependence—it is the autonomic, not the somatic, pathway whose signal is interrupted by losing the ganglion. (Choice D) confuses this autonomic motor ganglion with a dorsal-root sensory ganglion; autonomic ganglia contain the multipolar relay neurons of the motor pathway, not merely sensory cell bodies. This is a Scientific Reasoning and Problem Solving question because it requires applying the two-synapse versus one-synapse wiring difference to predict, from the site of the lesion, which effector loses control and which is spared.$ex15$, 'hard', '3A', $cc15$Nervous System Organization$cc15$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a15B$Wrongly routes somatic motor axons through an autonomic ganglion, treating all peripheral motor fibers as relayed.$a15B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a15C$Swaps which pathway depends on the ganglion, assigning the relay to the somatic instead of the autonomic system.$a15C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a15D$Mistakes a motor autonomic ganglion for a sensory dorsal-root ganglion, denying it any motor relay function.$a15D$ FROM q;

-- Q16 [Sympathetic vs Parasympathetic | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub16$Sympathetic vs Parasympathetic$sub16$, $qt16$A gazelle on the savanna spots a stalking lioness, and its sympathetic nervous system fires, releasing norepinephrine onto target organs throughout the body. Among the changes this triggers in the gazelle's respiratory tract is which of the following?$qt16$, $op16$[{"label": "A", "text": "The bronchi dilate, widening the air passages so more air can move into the lungs."}, {"label": "B", "text": "The bronchi constrict, narrowing the air passages so less air moves into the lungs."}, {"label": "C", "text": "Peristalsis in the gut speeds up, increasing the rate of digestion."}, {"label": "D", "text": "Heart rate slows, lowering the volume of blood pumped to the lungs."}]$op16$::jsonb, 'A', $ex16$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is A because the sympathetic ('fight or flight') response dilates the airways to raise oxygen intake during stress. OpenStax Biology 2e states that the physiological effects of sympathetic norepinephrine release include "dilating the trachea and bronchi (making it easier for the animal to breathe), increasing heart rate, and moving blood from the skin to the heart, muscles, and brain." Widening the bronchi reduces airway resistance so the fleeing gazelle can take in more air and oxygenate its blood for sustained running. (Choice A) is correct: sympathetic activation relaxes bronchial smooth muscle, dilating the bronchi to widen the airways. (Choice B) is the opposite, parasympathetic, effect — the vagus nerve is responsible for "constricting bronchial tubes in the lungs," not the sympathetic system. (Choice C) describes a parasympathetic 'rest and digest' effect; sympathetic activation inhibits digestion, whereas parasympathetic acetylcholine produces "stimulation of digestion." (Choice D) reverses the sympathetic effect on the heart, which actually involves "increasing heart rate," not slowing it. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established sympathetic effect on the airways rather than reasoning from supplied data.$ex16$, 'easy', '3A', $cc16$Nervous System Organization$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a16B$Swaps the sympathetic dilation for the opposing parasympathetic bronchoconstriction$a16B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a16C$States a real parasympathetic effect on a different organ (gut digestion) instead of the airway effect$a16C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a16D$Claims sympathetic activation lowers heart rate when it actually raises it$a16D$ FROM q;

-- Q17 [Sympathetic vs Parasympathetic | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub17$Sympathetic vs Parasympathetic$sub17$, $qt17$A pharmacologist records from a parasympathetic postganglionic fiber as it fires onto the smooth muscle of the gut wall and wants to identify the chemical the fiber releases at this neuroeffector junction. The transmitter the fiber secretes onto the target organ is:$qt17$, $op17$[{"label": "A", "text": "Norepinephrine, released onto adrenergic receptors on the target organ"}, {"label": "B", "text": "Acetylcholine, released onto muscarinic receptors on the target organ"}, {"label": "C", "text": "Epinephrine, released into the bloodstream to reach the target organ"}, {"label": "D", "text": "Acetylcholine, released only at the preceding ganglionic synapse"}]$op17$::jsonb, 'B', $ex17$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is B because the parasympathetic division is cholinergic at both of its synapses: the preganglionic fiber releases acetylcholine (ACh) onto the ganglionic neuron, and the postganglionic fiber in turn releases ACh onto the target organ, where it binds muscarinic receptors. OpenStax Biology 2e states that for the parasympathetic system "Most postganglionic neurons release acetylcholine onto target organs," and OpenStax Anatomy & Physiology 2e confirms that "The postganglionic parasympathetic fibers also release ACh, but the receptors on their targets are muscarinic receptors." This distinguishes the parasympathetic ("rest and digest") output from the sympathetic output, which is adrenergic at the target. (Choice A) Norepinephrine onto adrenergic receptors describes the sympathetic postganglionic fiber, not the parasympathetic one, so it reverses the two divisions. (Choice B) Acetylcholine onto muscarinic receptors is correct: it is the transmitter the postganglionic parasympathetic fiber releases onto the target organ. (Choice C) Epinephrine is a hormone the adrenal medulla secretes into the bloodstream during sympathetic activation, not a transmitter released at the parasympathetic target synapse. (Choice D) ACh is indeed released at the ganglionic synapse, but it is also the postganglionic parasympathetic transmitter at the organ, so restricting it to the ganglion alone is wrong. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established fact that the parasympathetic system uses acetylcholine as its postganglionic transmitter onto target organs.$ex17$, 'easy', '3A', $cc17$Nervous System Organization$cc17$, 'biology', 1, 75
  ) RETURNING id
)
