UNION ALL SELECT id, 'B', 'adjacent_fact', $a19B$Substituting the adrenal-medulla blood-borne hormone (epinephrine) for the synaptic transmitter (norepinephrine)$a19B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a19D$Attributing a parasympathetic/cholinergic-linked vasodilator signal (nitric oxide) to a sympathetic fiber$a19D$ FROM q;

-- Q20 [Sympathetic vs Parasympathetic | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub20$Sympathetic vs Parasympathetic$sub20$, $qt20$A patient is given a drug that selectively blocks muscarinic acetylcholine receptors throughout the body, while nicotinic and adrenergic receptors remain fully functional. A clinician monitors the patient's heart rate, gut peristalsis, and the transmitter signaling of both autonomic divisions.$qt20$, $op20$[{"label": "A", "text": "Sympathetic acceleration of the heart and dilation of the bronchi are blocked, while the parasympathetic effects on heart rate and digestion continue normally."}, {"label": "B", "text": "Both the sympathetic and the parasympathetic effects on heart rate are abolished, because all postganglionic autonomic transmission onto target organs requires muscarinic receptors."}, {"label": "C", "text": "All ganglionic transmission stops, so neither the sympathetic nor the parasympathetic division can deliver any signal to its target organs."}, {"label": "D", "text": "Parasympathetic slowing of the heart and stimulation of peristalsis are blocked, so heart rate rises and gut motility falls, while sympathetic effects persist through norepinephrine on adrenergic receptors."}]$op20$::jsonb, 'D', $ex20$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is D because postganglionic parasympathetic fibers act through acetylcholine on muscarinic receptors, whereas postganglionic sympathetic fibers act through norepinephrine on adrenergic receptors, so a muscarinic blocker silences only the parasympathetic output to target organs. The text states that postganglionic parasympathetic fibers release ACh onto muscarinic receptors while "Postganglionic sympathetic fibers release norepinephrine," and that when ACh "binds to a muscarinic receptor... the heart rate slows," whereas norepinephrine binding an adrenergic receptor makes the heart "rate increase" (A&P 2e). Biology 2e adds that parasympathetic ACh effects "include slowing of heart rate, lowered blood pressure, and stimulation of digestion." With muscarinic receptors blocked, those rest-and-digest brakes are removed, so heart rate climbs toward its intrinsic rate and peristalsis falls, while the norepinephrine-driven sympathetic effects on adrenergic receptors are untouched. (Choice A) is reversed: it is the parasympathetic effects, not the sympathetic ones, that depend on muscarinic receptors, and sympathetic acceleration and bronchial dilation run through norepinephrine on adrenergic receptors, which the drug does not block. (Choice B) wrongly assumes all postganglionic transmission is muscarinic, but postganglionic sympathetic fibers release norepinephrine onto adrenergic receptors, so the sympathetic effect on the heart survives. (Choice C) confuses ganglionic with postganglionic signaling: ganglionic transmission uses nicotinic ACh receptors, which a muscarinic blocker does not affect, so signals still reach the ganglia of both divisions. (Choice D) correctly predicts loss of parasympathetic muscarinic effects with intact adrenergic sympathetic effects. This is a Scientific Reasoning and Problem Solving question because it requires chaining the receptor pharmacology of each autonomic division to predict which specific organ effects fail and which persist when one receptor class is selectively blocked.$ex20$, 'hard', '3A', $cc20$Nervous System Organization$cc20$, 'biology', 2, 165
  ) RETURNING id
)
