UNION ALL SELECT id, 'B', 'misconception', $a20B$Assumes all postganglionic autonomic transmission uses muscarinic ACh receptors, ignoring sympathetic adrenergic signaling$a20B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a20C$Confuses ganglionic (nicotinic) transmission with target-organ (muscarinic) transmission, claiming all signaling stops$a20C$ FROM q;

-- Q21 [Reflex Arcs | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub21$Reflex Arcs$sub21$, $qt21$During a routine physical, a physician taps a patient's patellar tendon and the lower leg extends in the knee-jerk reflex. A student traces the neural pathway responsible for this response within the spinal cord. How many synapses connect the neurons in this reflex pathway, and between which neurons does the connection occur?$qt21$, $op21$[{"label": "A", "text": "A single synapse, located directly between a sensory neuron and a motor neuron"}, {"label": "B", "text": "Two synapses, with one interneuron interposed between the sensory neuron and the motor neuron"}, {"label": "C", "text": "Three synapses connecting three successive neurons that relay the signal up to the brain"}, {"label": "D", "text": "A single synapse, located directly between two motor neurons rather than a sensory and a motor neuron"}]$op21$::jsonb, 'A', $ex21$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is A because the knee-jerk (patellar) reflex is a monosynaptic reflex arc, mediated by exactly one synapse formed directly between the sensory neuron carrying information into the spinal cord and the motor neuron carrying the command back out to the muscle. OpenStax Biology 2e states that "the knee reflex that a doctor tests during a routine physical is controlled by a single synapse between a sensory neuron and a motor neuron," and notes that such reflexes are extremely fast precisely because they involve only this local connection with no interneuron interposed in the arc itself. Although interneurons in the spinal column do relay a separate copy of the information up to the brain, those connections are not part of the reflex arc that produces the leg extension. (Choice A) is correct: one synapse links the sensory neuron directly to the motor neuron, the defining feature of a monosynaptic arc. (Choice B) is wrong because inserting an interneuron to create two synapses describes a polysynaptic arc, not the monosynaptic knee-jerk. (Choice C) is wrong because three successive neurons describe the ascending dorsal column sensory pathway to the brain, not the reflex arc. (Choice D) is wrong because the single synapse joins a sensory neuron to a motor neuron, not two motor neurons. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined wiring of the monosynaptic patellar reflex arc as described in the text.$ex21$, 'easy', '3A', $cc21$Nervous System Organization$cc21$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
