SELECT id, 'A', 'partial_truth', $a22A$Correctly defines a monosynaptic arc but misapplies it to the interneuron-containing withdrawal reflex; the direct sensory-to-motor wiring actually describes the knee-jerk stretch reflex$a22A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a22C$Conflates 'involuntary/reflexive' with 'autonomic'; withdrawal is a somatic skeletal-muscle reflex, not a visceral autonomic one$a22C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a22D$Places the integration step in the brain stem (cranial reflex) rather than the spinal cord where this somatic spinal reflex is integrated$a22D$ FROM q;

-- Q23 [Reflex Arcs | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub23$Reflex Arcs$sub23$, $qt23$A clinician taps a patient's patellar tendon and the patient's lower leg kicks forward within a few hundredths of a second, far faster than any voluntary movement the patient could initiate. A student is asked to explain why this withdrawal-type response is so rapid by identifying where the incoming sensory signal is processed and converted into the outgoing motor command. The student should locate that integration site at:$qt23$, $op23$[{"label": "A", "text": "the cerebral cortex, where conscious decisions about how to respond to the stimulus are generated"}, {"label": "B", "text": "the cerebellum, which calculates the appropriate motor response before the muscle contracts"}, {"label": "C", "text": "the spinal cord, where local synaptic connections link the sensory and motor neurons directly"}, {"label": "D", "text": "the thalamus, which relays the sensory signal onward before the motor command is produced"}]$op23$::jsonb, 'C', $ex23$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is C because a motor reflex is integrated within the spinal cord through local synaptic connections between the sensory and motor neurons, so the signal never has to travel up to the brain and back. Biology 2e states that 'The spinal cord also controls motor reflexes. These reflexes are quick... Reflexes are so fast because they involve local synaptic connections,' and that the knee reflex 'is controlled by a single synapse between a sensory neuron and a motor neuron.' Because the entire loop is closed at the level of the cord rather than the brain, the delay introduced by ascending and descending brain pathways is eliminated, which is precisely why the response outpaces any voluntary movement. (Choice A) The cerebral cortex handles conscious, voluntary processing, but simple somatic reflexes 'do not include the higher centers discussed for conscious or voluntary aspects of movement,' so the cortex is bypassed. (Choice B) The cerebellum 'is responsible for calculating the appropriate response' when modulating voluntary movement such as walking, but it fine-tunes those commands rather than serving as the integration center of the reflex arc itself. (Choice C) is correct because the reflex is processed by local synaptic connections in the spinal cord, the feature that makes the response fast. (Choice D) The thalamus is a relay station that projects sensory input 'on to the cerebral cortex,' a step in ascending pathways to conscious perception, not the site where the reflex command is generated. This is a Scientific Reasoning and Problem Solving question because the student must connect the observed speed of the response to the underlying wiring of the reflex arc and infer the anatomical level at which integration must occur.$ex23$, 'medium', '3A', $cc23$Nervous System Organization$cc23$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
