-- Q24 [Reflex Arcs | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub24$Reflex Arcs$sub24$, $qt24$A neurotoxin selectively kills the interposed interneurons of the spinal cord while sparing all sensory and motor neurons. A neurologist then tests two reflexes in an exposed patient: the withdrawal reflex evoked by a painful stimulus to the sole of the foot and the patellar (knee-jerk) reflex evoked by tapping the patellar tendon.$qt24$, $op24$[{"label": "A", "text": "Both reflexes are abolished, because every spinal reflex arc relays the sensory signal through an interposed interneuron before reaching the motor neuron."}, {"label": "B", "text": "The patellar knee-jerk reflex is abolished while the polysynaptic withdrawal reflex is preserved, because only the knee-jerk arc depends on an interneuron."}, {"label": "C", "text": "Both reflexes are preserved, because the direct sensory-to-motor synapse present in each arc bypasses the destroyed interneurons entirely."}, {"label": "D", "text": "The polysynaptic withdrawal reflex is abolished while the patellar knee-jerk reflex is preserved, because only the withdrawal arc depends on an interneuron."}]$op24$::jsonb, 'D', $ex24$This is a Biology question that falls under the content category 'Nervous System Organization'. The answer is D because the two reflexes differ in their wiring: the withdrawal reflex is polysynaptic and routes through a spinal interneuron, whereas the patellar knee-jerk reflex is monosynaptic and connects the sensory neuron directly to the motor neuron. OpenStax A&P 2e states that in the hot-stove withdrawal reflex the inhibition of the antagonist 'occurs through an interneuron in the spinal cord,' so destroying interneurons breaks that arc. OpenStax Biology 2e states that the knee reflex 'is controlled by a single synapse between a sensory neuron and a motor neuron,' so it has no interneuron to lose and continues to function. Therefore the withdrawal reflex is abolished while the knee-jerk reflex is preserved. (Choice A) is wrong because the monosynaptic knee-jerk arc has no interposed interneuron, so not every spinal reflex relays through one. (Choice B) reverses the dependency: it is the withdrawal arc, not the knee-jerk arc, that requires the interneuron. (Choice C) is a partial truth, since a direct sensory-to-motor synapse exists only in the monosynaptic knee-jerk arc; the polysynaptic withdrawal arc has no such bypass and so cannot be spared. (Choice D) is correct because only the withdrawal arc depends on the destroyed interneuron, leaving the monosynaptic knee-jerk intact. This is a Scientific Reasoning and Problem Solving question because it requires applying the structural difference between mono- and polysynaptic arcs to predict the differential outcome of a selective lesion.$ex24$, 'hard', '3A', $cc24$Nervous System Organization$cc24$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
